"""Padding-free MoE implementation behind the public MoE runtime API."""

from __future__ import annotations

from dataclasses import dataclass

import torch

from kestrel_kernels.cute_moe.config import CuteMoeConfig
from kestrel_kernels.cute_moe.config import is_block_scheduled_fp8_kernel
from kestrel_kernels.moe.api import (
    MoeCapacity,
    MoeExpertWeights,
    MoeLoraState,
    MoeSpec,
)
from kestrel_kernels.moe.lora.fused_kernel import LORA_MMA_BLOCK_M
from kestrel_kernels.moe.lora.route import lora_a_rank, lora_rank_bucket
from kestrel_kernels.moe.workspace import FixedWorkspaceBuffer

# Decode buckets (graph-captured) stay on the per-assignment GEMV LoRA
# kernels; larger eager batches use the tiled-MMA kernels over the
# (adapter, expert) block schedule.
_LORA_SEG_MIN_TOKENS = 64
# The GEMV kernels re-read adapter panels per assignment row, so they only
# stay competitive while segments are thin AND ranks are small; tiles win as
# soon as either grows.
_LORA_MMA_MIN_ROWS_PER_KEY = 32
_LORA_MMA_MIN_RANK = 32
# The tcgen expand's 128-row tiles need dense (adapter, expert) segments.
_LORA_TCGEN_MIN_ROWS_PER_KEY = 128
# Must match the gpu_arches of the lora_expand variants in
# scripts/precompile/cubin_bundles.py.
_LORA_TCGEN_ARCHES = (100, 110)


def _fp8_weight_as_uint8(weight: torch.Tensor, name: str) -> torch.Tensor:
    if weight.dtype == torch.uint8:
        return weight
    if weight.dtype == torch.float8_e4m3fn:
        return weight.view(torch.uint8)
    raise ValueError(f"compact MoE requires FP8 {name} expert weights")


def _down_weight_scale_layout(layout: str) -> str:
    return "block128" if layout == "block128_interleaved8" else layout


def _validate_fp8_scale_shape(
    scale: torch.Tensor,
    *,
    name: str,
    num_experts: int,
    n: int,
    k: int,
    layout: str,
) -> None:
    if layout == "channel":
        expected = (num_experts, n)
    elif layout == "block128":
        expected = (num_experts, (n + 127) // 128, (k + 127) // 128)
    elif layout == "block128_interleaved8":
        if n % 2 != 0:
            raise ValueError(f"{name} block128_interleaved8 requires even N")
        expected = (
            num_experts,
            2,
            ((n // 2) + 127) // 128,
            (k + 127) // 128,
        )
    else:
        raise ValueError(f"unsupported FP8 weight scale layout: {layout!r}")
    if tuple(scale.shape) != expected:
        raise ValueError(f"{name} must have shape {expected}, got {tuple(scale.shape)}")


@dataclass(frozen=True)
class CompactBlockSchedule:
    block_offsets: torch.Tensor
    block_expert_ids: torch.Tensor
    block_m: int
    num_experts: int

    def view(self, assignments: int) -> "CompactBlockSchedule":
        from kestrel_kernels.moe.routing import max_route_blocks

        max_blocks = max_route_blocks(assignments, self.num_experts, self.block_m)
        return CompactBlockSchedule(
            block_offsets=self.block_offsets[: max_blocks + 2],
            block_expert_ids=self.block_expert_ids[:max_blocks],
            block_m=self.block_m,
            num_experts=self.num_experts,
        )


@dataclass(frozen=True)
class CompactRoute:
    sorted_token_ids: torch.Tensor
    cu_seqlens_m: torch.Tensor
    cumsum_buffer: torch.Tensor
    block_schedule: CompactBlockSchedule | None

    def view(self, assignments: int) -> "CompactRoute":
        return CompactRoute(
            sorted_token_ids=self.sorted_token_ids[:assignments],
            cu_seqlens_m=self.cu_seqlens_m,
            cumsum_buffer=self.cumsum_buffer,
            block_schedule=(
                None if self.block_schedule is None else self.block_schedule.view(assignments)
            ),
        )


@dataclass
class CompactMoeWorkspace:
    up: FixedWorkspaceBuffer
    activation: FixedWorkspaceBuffer
    down: FixedWorkspaceBuffer
    output: FixedWorkspaceBuffer
    lora_up: FixedWorkspaceBuffer
    lora_down: FixedWorkspaceBuffer
    lora_sorted: FixedWorkspaceBuffer
    lora_cu_seqlens: FixedWorkspaceBuffer
    lora_cursors: FixedWorkspaceBuffer
    lora_block_start: FixedWorkspaceBuffer
    lora_block_key: FixedWorkspaceBuffer
    lora_n_blocks: FixedWorkspaceBuffer
    lora_rowscale_ones: FixedWorkspaceBuffer
    lora_rowscale_tw: FixedWorkspaceBuffer
    fp8_up_bits: FixedWorkspaceBuffer
    fp8_up_scale: FixedWorkspaceBuffer
    fp8_down_bits: FixedWorkspaceBuffer
    fp8_down_scale: FixedWorkspaceBuffer
    up_routed: FixedWorkspaceBuffer
    up_row_scale: FixedWorkspaceBuffer
    down_routed: FixedWorkspaceBuffer
    down_row_scale: FixedWorkspaceBuffer


def _make_workspace() -> CompactMoeWorkspace:
    return CompactMoeWorkspace(
        up=FixedWorkspaceBuffer("MoE compact up workspace"),
        activation=FixedWorkspaceBuffer("MoE compact activation workspace"),
        down=FixedWorkspaceBuffer("MoE compact down workspace"),
        output=FixedWorkspaceBuffer("MoE compact output workspace"),
        lora_up=FixedWorkspaceBuffer("MoE compact LoRA up workspace"),
        lora_down=FixedWorkspaceBuffer("MoE compact LoRA down workspace"),
        lora_sorted=FixedWorkspaceBuffer("MoE compact LoRA route ids workspace"),
        lora_cu_seqlens=FixedWorkspaceBuffer("MoE compact LoRA route offsets workspace"),
        lora_cursors=FixedWorkspaceBuffer("MoE compact LoRA route cursors workspace"),
        lora_block_start=FixedWorkspaceBuffer("MoE compact LoRA block starts workspace"),
        lora_block_key=FixedWorkspaceBuffer("MoE compact LoRA block keys workspace"),
        lora_n_blocks=FixedWorkspaceBuffer("MoE compact LoRA block count workspace"),
        lora_rowscale_ones=FixedWorkspaceBuffer("MoE compact LoRA row ones workspace"),
        lora_rowscale_tw=FixedWorkspaceBuffer("MoE compact LoRA row weight workspace"),
        fp8_up_bits=FixedWorkspaceBuffer("MoE compact FP8 up bits workspace"),
        fp8_up_scale=FixedWorkspaceBuffer("MoE compact FP8 up scale workspace"),
        fp8_down_bits=FixedWorkspaceBuffer("MoE compact FP8 down bits workspace"),
        fp8_down_scale=FixedWorkspaceBuffer("MoE compact FP8 down scale workspace"),
        up_routed=FixedWorkspaceBuffer("MoE compact up routed workspace"),
        up_row_scale=FixedWorkspaceBuffer("MoE compact up row scale workspace"),
        down_routed=FixedWorkspaceBuffer("MoE compact down routed workspace"),
        down_row_scale=FixedWorkspaceBuffer("MoE compact down row scale workspace"),
    )


def _reserve_workspace(
    workspace: CompactMoeWorkspace,
    spec: MoeSpec,
    capacity: MoeCapacity,
    device: torch.device,
    *,
    materialize_dtype: torch.dtype | None,
) -> None:
    max_tokens = capacity.max_tokens
    assignments = max_tokens * spec.top_k
    reservations = [
        (workspace.up, (max_tokens, spec.top_k, spec.intermediate_size * 2), spec.dtype),
        (workspace.activation, (assignments, spec.intermediate_size), spec.dtype),
        (workspace.down, (max_tokens, spec.top_k, spec.hidden_size), spec.dtype),
        (workspace.output, (max_tokens, spec.hidden_size), spec.dtype),
        (workspace.fp8_up_bits, (max_tokens, spec.hidden_size), torch.uint8),
        (workspace.fp8_up_scale, (max_tokens,), torch.float32),
    ]
    if materialize_dtype is not None:
        reservations.extend(
            [
                (workspace.up_routed, (assignments, spec.hidden_size), materialize_dtype),
                (workspace.up_row_scale, (assignments,), torch.float32),
                (
                    workspace.down_routed,
                    (assignments, spec.intermediate_size),
                    materialize_dtype,
                ),
                (workspace.down_row_scale, (assignments,), torch.float32),
            ]
        )
    else:
        reservations.extend(
            [
                (workspace.fp8_down_bits, (assignments, spec.intermediate_size), torch.uint8),
                (workspace.fp8_down_scale, (assignments,), torch.float32),
            ]
        )
    if capacity.max_loras > 0 and capacity.max_lora_rank > 0:
        lora_rank = lora_rank_bucket(capacity.max_lora_rank)
        lora_keys = capacity.max_loras * spec.num_experts
        # Worst case: every (adapter, expert) key adds one partial block.
        lora_blocks = -(-assignments // LORA_MMA_BLOCK_M) + lora_keys
        reservations.extend(
            [
                (workspace.lora_up, (assignments, lora_rank), spec.dtype),
                (workspace.lora_down, (assignments, lora_rank), spec.dtype),
                (workspace.lora_sorted, (assignments,), torch.int32),
                (workspace.lora_cu_seqlens, (lora_keys + 1,), torch.int32),
                (workspace.lora_cursors, (lora_keys,), torch.int32),
                (workspace.lora_block_start, (lora_blocks,), torch.int32),
                (workspace.lora_block_key, (lora_blocks,), torch.int32),
                (workspace.lora_n_blocks, (1,), torch.int32),
                (workspace.lora_rowscale_ones, (assignments,), torch.float32),
                (workspace.lora_rowscale_tw, (assignments,), torch.float32),
            ]
        )
    for buffer, shape, dtype in reservations:
        buffer.reserve(shape, device=device, dtype=dtype)


def _make_route_workspace(
    *,
    max_tokens: int,
    top_k: int,
    num_experts: int,
    block_m: int | None,
    device: torch.device,
) -> CompactRoute:
    assignments = max_tokens * top_k
    if block_m is None:
        block_schedule = None
    else:
        from kestrel_kernels.moe.routing import max_route_blocks

        max_blocks = max_route_blocks(assignments, num_experts, block_m)
        block_schedule = CompactBlockSchedule(
            block_offsets=torch.empty((max_blocks + 2,), dtype=torch.int32, device=device),
            block_expert_ids=torch.empty((max_blocks,), dtype=torch.int32, device=device),
            block_m=block_m,
            num_experts=num_experts,
        )
    return CompactRoute(
        sorted_token_ids=torch.empty((assignments,), dtype=torch.int32, device=device),
        cu_seqlens_m=torch.empty((num_experts + 1,), dtype=torch.int32, device=device),
        cumsum_buffer=torch.empty((num_experts,), dtype=torch.int32, device=device),
        block_schedule=block_schedule,
    )


@dataclass
class CompactMoeImpl:
    spec: MoeSpec
    capacity: MoeCapacity
    device: torch.device
    up_config: CuteMoeConfig
    down_config: CuteMoeConfig
    route: CompactRoute
    workspace: CompactMoeWorkspace

    def _route_view(self, num_tokens: int) -> CompactRoute:
        return self.route.view(num_tokens * self.spec.top_k)

    def _validate_inputs(
        self,
        x: torch.Tensor,
        topk_ids: torch.Tensor,
        topk_weights: torch.Tensor,
        weights: MoeExpertWeights,
    ) -> tuple[
        torch.Tensor,
        torch.Tensor,
        torch.Tensor | None,
        torch.Tensor,
        torch.Tensor | None,
        str,
    ]:
        if self.spec.activation == "swiglu" and weights.weight_scale_layout == "block128":
            # The native SwiGLU kernel only implements the 8-row gate/up
            # interleave (swiglu/kernel.py), so it cannot pair a plain block128
            # slab's contiguous [gate | up] halves. Nothing produces that
            # combination today (the only swiglu producer ships
            # block128_interleaved8); reject it rather than mispair silently --
            # the interleave is a row permutation, so no shape check can catch
            # it. A spec/weights contract error, so it precedes the device checks.
            raise ValueError(
                "swiglu MoE requires an 8-row gate/up interleaved up slab "
                '("channel" or "block128_interleaved8" scales); plain '
                '"block128" keeps contiguous [gate | up] halves'
            )
        if self.spec.activation == "geglu" and weights.weight_scale_layout != "block128":
            raise ValueError(
                "geglu MoE requires a contiguous [gate | up] up slab "
                '("block128" layout)'
            )
        if x.device != self.device:
            raise ValueError(f"x must be on prepared device {self.device}, got {x.device}")
        if x.device.type != "cuda":
            raise ValueError("compact MoE requires CUDA tensors")
        if x.dtype != torch.bfloat16:
            raise ValueError("compact MoE requires BF16 activations")
        if x.ndim != 2 or x.shape[1] != self.spec.hidden_size:
            raise ValueError(
                f"x must have shape [tokens, {self.spec.hidden_size}], got {tuple(x.shape)}"
            )
        if x.shape[0] > self.capacity.max_tokens:
            raise RuntimeError(
                f"MoE handle capacity overflow: got {x.shape[0]} tokens, "
                f"capacity is {self.capacity.max_tokens}"
            )
        if not x.is_contiguous():
            raise ValueError("x must be contiguous")
        if topk_ids.shape != (x.shape[0], self.spec.top_k):
            raise ValueError(
                f"topk_ids must have shape [{x.shape[0]}, {self.spec.top_k}]"
            )
        if topk_weights.shape != (x.shape[0], self.spec.top_k):
            raise ValueError(
                f"topk_weights must have shape [{x.shape[0]}, {self.spec.top_k}]"
            )
        if topk_ids.dtype != torch.int32:
            raise ValueError("topk_ids must be int32 for allocation-free MoE forward")
        if topk_weights.dtype not in (torch.bfloat16, torch.float32):
            raise ValueError("topk_weights must be bf16 or float32")
        if not topk_ids.is_contiguous() or not topk_weights.is_contiguous():
            raise ValueError("topk_ids and topk_weights must be contiguous")
        if weights.up.device != x.device or weights.down.device != x.device:
            raise ValueError("expert weights must be on the same device as x")

        expected_up_shape = (
            self.spec.num_experts,
            self.spec.intermediate_size * 2,
            self.spec.hidden_size,
        )
        expected_down_shape = (
            self.spec.num_experts,
            self.spec.hidden_size,
            self.spec.intermediate_size,
        )
        if self.spec.weight_format == "bf16":
            if weights.up.dtype != torch.bfloat16 or weights.down.dtype != torch.bfloat16:
                raise ValueError("BF16 MoE requires BF16 expert weights")
            if not weights.up.is_contiguous() or not weights.down.is_contiguous():
                raise ValueError("BF16 expert weights must be contiguous")
            if tuple(weights.up.shape) != expected_up_shape:
                raise ValueError(
                    "up expert weights must have shape "
                    "[num_experts, 2 * intermediate_size, hidden_size]"
                )
            if tuple(weights.down.shape) != expected_down_shape:
                raise ValueError(
                    "down expert weights must have shape "
                    "[num_experts, hidden_size, intermediate_size]"
                )
            # BF16 has no scale tensor, but this field also declares the up
            # slab's gate/up row order. Preserve it so activation pairing is
            # independent of quantization format.
            return (
                topk_weights,
                weights.up,
                None,
                weights.down,
                None,
                weights.weight_scale_layout,
            )

        up_weight = _fp8_weight_as_uint8(weights.up, "up")
        down_weight = _fp8_weight_as_uint8(weights.down, "down")
        if weights.up_scale is None or weights.down_scale is None:
            raise ValueError("FP8 MoE weights require up_scale and down_scale")
        if weights.up_scale.device != x.device or weights.down_scale.device != x.device:
            raise ValueError("expert scales must be on the same device as x")
        if tuple(up_weight.shape) != expected_up_shape:
            raise ValueError(
                "up expert weights must have shape "
                "[num_experts, 2 * intermediate_size, hidden_size]"
            )
        if tuple(down_weight.shape) != expected_down_shape:
            raise ValueError(
                "down expert weights must have shape "
                "[num_experts, hidden_size, intermediate_size]"
            )
        scale_layout = weights.weight_scale_layout
        _validate_fp8_scale_shape(
            weights.up_scale,
            name="up_scale",
            num_experts=self.spec.num_experts,
            n=self.spec.intermediate_size * 2,
            k=self.spec.hidden_size,
            layout=scale_layout,
        )
        _validate_fp8_scale_shape(
            weights.down_scale,
            name="down_scale",
            num_experts=self.spec.num_experts,
            n=self.spec.hidden_size,
            k=self.spec.intermediate_size,
            layout=_down_weight_scale_layout(scale_layout),
        )
        return (
            topk_weights,
            up_weight,
            weights.up_scale,
            down_weight,
            weights.down_scale,
            scale_layout,
        )

    def _validate_lora_capacity(self, lora: MoeLoraState) -> None:
        weight_loras = int(lora.up_a.shape[0]) // self.spec.num_experts
        if weight_loras > self.capacity.max_loras:
            raise RuntimeError(
                f"MoE LoRA capacity overflow: got {weight_loras} LoRAs, "
                f"capacity is {self.capacity.max_loras}"
            )
        max_rank = max(int(lora.up_a.shape[1]), int(lora.down_a.shape[1]))
        if max_rank > self.capacity.max_lora_rank:
            raise RuntimeError(
                f"MoE LoRA rank overflow: got rank {max_rank}, "
                f"capacity is {self.capacity.max_lora_rank}"
            )

    def _output(self, x: torch.Tensor, out: torch.Tensor | None) -> torch.Tensor:
        num_tokens = int(x.shape[0])
        if out is None:
            return self.workspace.output.get(
                (num_tokens, self.spec.hidden_size),
                device=x.device,
                dtype=x.dtype,
            )
        if (
            tuple(out.shape) != (num_tokens, self.spec.hidden_size)
            or out.device != x.device
            or out.dtype != x.dtype
            or not out.is_contiguous()
        ):
            raise ValueError(
                f"out must be contiguous BF16 with shape "
                f"[{num_tokens}, {self.spec.hidden_size}]"
            )
        return out

    def _lora_seg_route(
        self,
        x: torch.Tensor,
        topk_ids: torch.Tensor,
        topk_weights: torch.Tensor,
        lora: MoeLoraState,
    ):
        from kestrel_kernels.arch import get_cuda_sm
        from kestrel_kernels.moe.lora.cute import (
            LoraSegRoute,
            invoke_lora_route_topk,
        )

        assignments = int(x.shape[0]) * self.spec.top_k
        routes = max(1, int(lora.metadata.active_lora_ids.numel()))
        lora_keys = self.capacity.max_loras * self.spec.num_experts
        max_blocks = -(-assignments // LORA_MMA_BLOCK_M) + (
            routes * self.spec.num_experts
        )
        sorted_ids = self.workspace.lora_sorted.get(
            (assignments,), device=x.device, dtype=torch.int32
        )
        cu_seqlens = self.workspace.lora_cu_seqlens.get(
            (lora_keys + 1,), device=x.device, dtype=torch.int32
        )
        cursors = self.workspace.lora_cursors.get(
            (lora_keys,), device=x.device, dtype=torch.int32
        )
        block_start = self.workspace.lora_block_start.get(
            (max_blocks,), device=x.device, dtype=torch.int32
        )
        block_key = self.workspace.lora_block_key.get(
            (max_blocks,), device=x.device, dtype=torch.int32
        )
        n_blocks = self.workspace.lora_n_blocks.get(
            (1,), device=x.device, dtype=torch.int32
        )
        rowscale_ones = self.workspace.lora_rowscale_ones.get(
            (assignments,), device=x.device, dtype=torch.float32
        )
        rowscale_tw = self.workspace.lora_rowscale_tw.get(
            (assignments,), device=x.device, dtype=torch.float32
        )
        invoke_lora_route_topk(
            topk_ids=topk_ids,
            active_token_ids=lora.metadata.active_token_ids,
            active_lora_ids=lora.metadata.active_lora_ids,
            active_lora_meta=lora.metadata.active_lora_meta,
            topk_weights=topk_weights,
            sorted_ids=sorted_ids,
            cu_seqlens=cu_seqlens,
            cursors=cursors,
            block_row_start=block_start,
            block_key=block_key,
            n_blocks=n_blocks,
            rowscale_ones=rowscale_ones,
            rowscale_tw=rowscale_tw,
            top_k=self.spec.top_k,
            num_experts=self.spec.num_experts,
        )
        # The tcgen expand wants dense 128-row tiles: gate on segment
        # density so half-empty tiles don't out-cost the warp-MMA expand.
        rows_per_key = assignments // (self.spec.num_experts * routes)
        # Datacenter Blackwell only: consumer sm_120 has no tcgen05 and the
        # lora_expand AOT variants ship for {100, 110} alone — a >= check
        # would strand sm_120 with no bundled variant instead of falling
        # back to the warp-MMA expand.
        use_tcgen = (
            get_cuda_sm() in _LORA_TCGEN_ARCHES
            and rows_per_key >= _LORA_TCGEN_MIN_ROWS_PER_KEY
        )
        return LoraSegRoute(
            sorted_ids=sorted_ids,
            cu_seqlens=cu_seqlens,
            block_row_start=block_start,
            block_key=block_key,
            n_blocks=n_blocks,
            rowscale_ones=rowscale_ones,
            rowscale_tw=rowscale_tw,
            use_tcgen_expand=use_tcgen,
        )

    def _lora_scratch(
        self,
        *,
        x: torch.Tensor,
        lora: MoeLoraState,
        down: bool,
    ) -> torch.Tensor:
        return (self.workspace.lora_down if down else self.workspace.lora_up).get(
            (x.shape[0] * self.spec.top_k, lora_a_rank(lora, down)),
            device=x.device,
            dtype=x.dtype,
        )

    def _route(self, topk_ids: torch.Tensor, route: CompactRoute) -> None:
        from kestrel_kernels.moe.routing import moe_route_topk, moe_route_topk_schedule

        schedule = route.block_schedule
        if schedule is not None:
            moe_route_topk_schedule(
                topk_ids,
                self.spec.num_experts,
                route.sorted_token_ids,
                schedule.block_offsets,
                schedule.block_expert_ids,
                block_m=schedule.block_m,
                cumsum_buffer=route.cumsum_buffer,
            )
            return
        moe_route_topk(
            topk_ids,
            self.spec.num_experts,
            route.sorted_token_ids,
            route.cu_seqlens_m,
            route.cumsum_buffer,
        )

    def _run_activation(
        self, up_out: torch.Tensor, num_tokens: int, *, up_interleaved: bool
    ) -> torch.Tensor:
        activation_in = up_out.view(num_tokens * self.spec.top_k, -1)
        activation_out = self.workspace.activation.get(
            (num_tokens * self.spec.top_k, self.spec.intermediate_size),
            device=up_out.device,
            dtype=up_out.dtype,
        )
        if self.spec.activation == "gelu":
            from kestrel_kernels.gelu_residual import gelu_residual_cute

            gelu_residual_cute(activation_out, activation_in, interleaved=up_interleaved)
        elif self.spec.activation == "swiglu":
            # Interleave-only; _validate_inputs rejects plain block128 + swiglu.
            from kestrel_kernels.swiglu import gated_activation_into

            gated_activation_into(
                activation_out,
                activation_in,
                activation="silu",
                layout="interleaved_i8",
            )
        elif self.spec.activation == "geglu":
            from kestrel_kernels.swiglu import gated_activation_into

            gated_activation_into(
                activation_out,
                activation_in,
                activation="gelu_tanh",
                layout="contiguous",
            )
        else:
            raise ValueError(f"unsupported MoE activation: {self.spec.activation!r}")
        return activation_out

    def _invoke_up(
        self,
        x: torch.Tensor,
        topk_ids: torch.Tensor,
        up_weight: torch.Tensor,
        up_scale: torch.Tensor | None,
        up_out: torch.Tensor,
        route: CompactRoute,
        weight_scale_layout: str,
    ) -> None:
        num_tokens = int(x.shape[0])
        assignments = num_tokens * self.spec.top_k
        if self.spec.weight_format == "bf16":
            from kestrel_kernels.cute_moe.dispatch import invoke_cute_moe_up_bf16_tcgen
            from kestrel_kernels.moe.routing import moe_route_topk_materialize_bf16

            routed = self.workspace.up_routed.get(
                (assignments, self.spec.hidden_size),
                device=x.device,
                dtype=torch.bfloat16,
            )
            row_scale = self.workspace.up_row_scale.get(
                (assignments,), device=x.device, dtype=torch.float32
            )
            moe_route_topk_materialize_bf16(
                topk_ids=topk_ids,
                num_experts=self.spec.num_experts,
                A=x,
                sorted_token_ids=route.sorted_token_ids,
                cu_seqlens_m=route.cu_seqlens_m,
                cumsum_buffer=route.cumsum_buffer,
                A_routed=routed,
                row_scale=row_scale,
            )
            invoke_cute_moe_up_bf16_tcgen(
                routed,
                up_weight,
                up_out,
                sorted_token_ids=route.sorted_token_ids,
                cu_seqlens_m=route.cu_seqlens_m,
                row_scale=row_scale,
                config=self.up_config,
            )
            return

        from kestrel_kernels.fp8_quant_cute import fp8_quant_cute

        assert up_scale is not None
        a_bits = self.workspace.fp8_up_bits.get(
            (num_tokens, self.spec.hidden_size),
            device=x.device,
            dtype=torch.uint8,
        )
        a_scale = self.workspace.fp8_up_scale.get(
            (num_tokens,),
            device=x.device,
            dtype=torch.float32,
        )
        fp8_quant_cute(a_bits, a_scale, x)
        if self.up_config.kernel_type == "tcgen":
            if weight_scale_layout != "channel":
                raise ValueError("tcgen FP8 MoE does not support block weight scales")
            from kestrel_kernels.cute_moe.dispatch import invoke_cute_moe_up_fp8_tcgen

            routed_bits = self.workspace.up_routed.get(
                (num_tokens * self.spec.top_k, self.spec.hidden_size),
                device=x.device,
                dtype=torch.uint8,
            )
            row_scale = self.workspace.up_row_scale.get(
                (num_tokens * self.spec.top_k,),
                device=x.device,
                dtype=torch.float32,
            )
            invoke_cute_moe_up_fp8_tcgen(
                a_bits,
                a_scale,
                up_weight,
                up_scale,
                up_out,
                sorted_token_ids=route.sorted_token_ids,
                cu_seqlens_m=route.cu_seqlens_m,
                A_routed_bits=routed_bits,
                row_scale=row_scale,
                config=self.up_config,
            )
        else:
            from kestrel_kernels.cute_moe.dispatch import invoke_cute_moe_up_fp8_compact

            schedule = route.block_schedule
            assert schedule is not None
            invoke_cute_moe_up_fp8_compact(
                a_bits,
                a_scale,
                up_weight,
                up_scale,
                up_out,
                sorted_token_ids=route.sorted_token_ids,
                block_offsets=schedule.block_offsets,
                block_expert_ids=schedule.block_expert_ids,
                config=self.up_config,
                weight_scale_layout=weight_scale_layout,
            )

    def _invoke_down(
        self,
        down_in: torch.Tensor,
        topk_weights: torch.Tensor,
        down_weight: torch.Tensor,
        down_scale: torch.Tensor | None,
        down_out: torch.Tensor,
        route: CompactRoute,
        weight_scale_layout: str,
    ) -> None:
        num_tokens = int(down_out.shape[0])
        assignments = num_tokens * self.spec.top_k
        if self.spec.weight_format == "bf16":
            from kestrel_kernels.cute_moe.dispatch import invoke_cute_moe_down_bf16_tcgen
            from kestrel_kernels.moe.routing import moe_route_materialize_bf16

            routed = self.workspace.down_routed.get(
                (assignments, self.spec.intermediate_size),
                device=down_in.device,
                dtype=torch.bfloat16,
            )
            row_scale = self.workspace.down_row_scale.get(
                (assignments,), device=down_in.device, dtype=torch.float32
            )
            moe_route_materialize_bf16(
                kind="down",
                A=down_in,
                topk_weights=topk_weights.view(-1),
                sorted_token_ids=route.sorted_token_ids,
                cu_seqlens_m=route.cu_seqlens_m,
                A_routed=routed,
                row_scale=row_scale,
                top_k=1,
                num_experts=self.spec.num_experts,
            )
            invoke_cute_moe_down_bf16_tcgen(
                routed,
                down_weight,
                down_out,
                sorted_token_ids=route.sorted_token_ids,
                cu_seqlens_m=route.cu_seqlens_m,
                row_scale=row_scale,
                config=self.down_config,
            )
            return

        from kestrel_kernels.fp8_quant_cute import fp8_quant_cute
        from kestrel_kernels.cute_moe.dispatch import invoke_cute_moe_down_fp8_compact

        assert down_scale is not None
        a_bits = self.workspace.fp8_down_bits.get(
            (assignments, self.spec.intermediate_size),
            device=down_in.device,
            dtype=torch.uint8,
        )
        a_scale = self.workspace.fp8_down_scale.get(
            (assignments,),
            device=down_in.device,
            dtype=torch.float32,
        )
        fp8_quant_cute(a_bits, a_scale, down_in)
        schedule = route.block_schedule
        assert schedule is not None
        invoke_cute_moe_down_fp8_compact(
            a_bits,
            a_scale,
            down_weight,
            down_scale,
            down_out,
            topk_weights=topk_weights.view(-1),
            sorted_token_ids=route.sorted_token_ids,
            block_offsets=schedule.block_offsets,
            block_expert_ids=schedule.block_expert_ids,
            config=self.down_config,
            weight_scale_layout=_down_weight_scale_layout(weight_scale_layout),
        )

    def _invoke_down_activated_tcgen(
        self,
        base_up: torch.Tensor,
        activation: torch.Tensor,
        topk_weights: torch.Tensor,
        down_weight: torch.Tensor,
        down_scale: torch.Tensor,
        down_out: torch.Tensor,
        route: CompactRoute,
        weight_scale_layout: str,
    ) -> None:
        if weight_scale_layout != "channel":
            raise ValueError("tcgen FP8 MoE does not support block weight scales")
        from kestrel_kernels.cute_moe.dispatch import invoke_cute_moe_down_activated_tcgen

        num_tokens = int(down_out.shape[0])
        assignments = num_tokens * self.spec.top_k
        routed_bits = self.workspace.down_routed.get(
            (assignments, self.spec.intermediate_size),
            device=base_up.device,
            dtype=torch.uint8,
        )
        row_scale = self.workspace.down_row_scale.get(
            (assignments,),
            device=base_up.device,
            dtype=torch.float32,
        )
        invoke_cute_moe_down_activated_tcgen(
            base_up,
            activation,
            down_weight,
            down_scale,
            down_out,
            topk_weights=topk_weights.view(-1),
            sorted_token_ids=route.sorted_token_ids,
            cu_seqlens_m=route.cu_seqlens_m,
            A_routed_bits=routed_bits,
            row_scale=row_scale,
            config=self.down_config,
        )

    def _invoke_down_activated_bf16_tcgen(
        self,
        base_up: torch.Tensor,
        topk_weights: torch.Tensor,
        down_weight: torch.Tensor,
        down_out: torch.Tensor,
        route: CompactRoute,
        *,
        interleaved: bool,
    ) -> None:
        from kestrel_kernels.cute_moe.dispatch import invoke_cute_moe_down_bf16_tcgen
        from kestrel_kernels.moe.routing import moe_route_activate_materialize_bf16

        assignments = int(down_out.shape[0]) * self.spec.top_k
        routed = self.workspace.down_routed.get(
            (assignments, self.spec.intermediate_size),
            device=base_up.device,
            dtype=torch.bfloat16,
        )
        row_scale = self.workspace.down_row_scale.get(
            (assignments,), device=base_up.device, dtype=torch.float32
        )
        moe_route_activate_materialize_bf16(
            base_up=base_up.view(assignments, -1),
            topk_weights=topk_weights.view(-1),
            sorted_token_ids=route.sorted_token_ids,
            cu_seqlens_m=route.cu_seqlens_m,
            A_routed=routed,
            row_scale=row_scale,
            num_experts=self.spec.num_experts,
            activation=self.spec.activation,
            interleaved=interleaved,
        )
        invoke_cute_moe_down_bf16_tcgen(
            routed,
            down_weight,
            down_out,
            sorted_token_ids=route.sorted_token_ids,
            cu_seqlens_m=route.cu_seqlens_m,
            row_scale=row_scale,
            config=self.down_config,
        )

    def forward(
        self,
        *,
        x: torch.Tensor,
        topk_ids: torch.Tensor,
        topk_weights: torch.Tensor,
        weights: MoeExpertWeights,
        out: torch.Tensor | None,
        lora: MoeLoraState | None,
        base_up_out: torch.Tensor | None = None,
    ) -> torch.Tensor:
        route_weights, up_weight, up_scale, down_weight, down_scale, scale_layout = (
            self._validate_inputs(x, topk_ids, topk_weights, weights)
        )
        # Gated-GELU pairing must match the up slab's row order: engine
        # channel-scale slabs and block128_interleaved8 are 8-row gate/up
        # interleaved; plain block128 keeps contiguous [gate | up] halves
        # (same rule as moe/warpgemv.py and the fused warpgemv kernel).
        up_interleaved = scale_layout != "block128"
        if lora is not None:
            if self.spec.activation == "geglu":
                raise NotImplementedError("geglu MoE LoRA is not implemented")
            self._validate_lora_capacity(lora)

        num_tokens = int(x.shape[0])
        fused = self._output(x, out)
        route = self._route_view(num_tokens)
        if self.spec.weight_format != "bf16":
            self._route(topk_ids, route)
        # Above the CUDA-graph decode buckets the tiled-MMA LoRA kernels win:
        # one (adapter, expert)-sorted block schedule feeds both the up and
        # down apply, so every tile touches only its own adapter's rows.
        seg_route = None
        if lora is not None and num_tokens > _LORA_SEG_MIN_TOKENS:
            routes = max(1, int(lora.metadata.active_lora_ids.numel()))
            rows_per_key = (num_tokens * self.spec.top_k) // (
                self.spec.num_experts * routes
            )
            rank_hint = max(
                lora_a_rank(lora, down=False), lora_a_rank(lora, down=True)
            )
            if (
                rows_per_key >= _LORA_MMA_MIN_ROWS_PER_KEY
                or rank_hint >= _LORA_MMA_MIN_RANK
            ):
                seg_route = self._lora_seg_route(x, topk_ids, topk_weights, lora)

        up_out = self.workspace.up.get(
            (num_tokens, self.spec.top_k, self.spec.intermediate_size * 2),
            device=x.device,
            dtype=x.dtype,
            external=base_up_out,
        )
        self._invoke_up(
            x, topk_ids, up_weight, up_scale, up_out, route, scale_layout
        )

        fused_tcgen_down = (
            self.spec.weight_format == "fp8_e4m3"
            and self.down_config.kernel_type == "tcgen"
        )
        fused_bf16_tcgen_down = (
            self.spec.weight_format == "bf16"
            and self.down_config.kernel_type == "tcgen"
            and lora is None
        )
        if fused_tcgen_down or lora is not None:
            down_in = self.workspace.activation.get(
                (num_tokens * self.spec.top_k, self.spec.intermediate_size),
                device=up_out.device,
                dtype=up_out.dtype,
            )
        elif fused_bf16_tcgen_down:
            down_in = None
        else:
            down_in = self._run_activation(
                up_out, num_tokens, up_interleaved=up_interleaved
            )

        if lora is not None:
            assert down_in is not None
            if fused_tcgen_down:
                from kestrel_kernels.moe.lora.cute import apply_moe_lora_up

                apply_moe_lora_up(
                    x=x,
                    base_up=up_out,
                    lora_a=lora.up_a,
                    lora_b=lora.up_b,
                    topk_ids=topk_ids,
                    active_token_ids=lora.metadata.active_token_ids,
                    active_lora_ids=lora.metadata.active_lora_ids,
                    active_lora_meta=lora.metadata.active_lora_meta,
                    num_experts=self.spec.num_experts,
                    scratch=self._lora_scratch(x=x, lora=lora, down=False),
                    lora_ranks=lora.lora_ranks,
                    active_lora_max_rank=lora.metadata.active_lora_max_rank,
                    seg_route=seg_route,
                )
            else:
                if self.spec.activation == "gelu":
                    from kestrel_kernels.moe.lora.cute import apply_moe_lora_up_gelu

                    apply_moe_lora_up_gelu(
                        x=x,
                        base_up=up_out,
                        activation=down_in,
                        lora_a=lora.up_a,
                        lora_b=lora.up_b,
                        topk_ids=topk_ids,
                        active_token_ids=lora.metadata.active_token_ids,
                        active_lora_ids=lora.metadata.active_lora_ids,
                        active_lora_meta=lora.metadata.active_lora_meta,
                        num_experts=self.spec.num_experts,
                        scratch=self._lora_scratch(x=x, lora=lora, down=False),
                        lora_ranks=lora.lora_ranks,
                        active_lora_max_rank=lora.metadata.active_lora_max_rank,
                        seg_route=seg_route,
                        interleaved=up_interleaved,
                    )
                elif self.spec.activation == "swiglu":
                    # Interleave-only; _validate_inputs rejects plain block128.
                    from kestrel_kernels.moe.lora.cute import apply_moe_lora_up
                    from kestrel_kernels.swiglu import gated_activation_into

                    apply_moe_lora_up(
                        x=x,
                        base_up=up_out,
                        lora_a=lora.up_a,
                        lora_b=lora.up_b,
                        topk_ids=topk_ids,
                        active_token_ids=lora.metadata.active_token_ids,
                        active_lora_ids=lora.metadata.active_lora_ids,
                        active_lora_meta=lora.metadata.active_lora_meta,
                        num_experts=self.spec.num_experts,
                        scratch=self._lora_scratch(x=x, lora=lora, down=False),
                        lora_ranks=lora.lora_ranks,
                        active_lora_max_rank=lora.metadata.active_lora_max_rank,
                        seg_route=seg_route,
                    )
                    gated_activation_into(
                        down_in,
                        up_out.view(num_tokens * self.spec.top_k, -1),
                        activation="silu",
                        layout="interleaved_i8",
                    )
                else:
                    raise ValueError(
                        f"unsupported MoE activation: {self.spec.activation!r}"
                    )

        down_out = self.workspace.down.get(
            (num_tokens, self.spec.top_k, self.spec.hidden_size),
            device=x.device,
            dtype=x.dtype,
        )
        if fused_tcgen_down:
            assert down_in is not None
            self._invoke_down_activated_tcgen(
                up_out,
                down_in,
                route_weights,
                down_weight,
                down_scale,
                down_out,
                route,
                scale_layout,
            )
        elif fused_bf16_tcgen_down:
            self._invoke_down_activated_bf16_tcgen(
                up_out,
                route_weights,
                down_weight,
                down_out,
                route,
                interleaved=up_interleaved,
            )
        else:
            assert down_in is not None
            self._invoke_down(
                down_in,
                route_weights,
                down_weight,
                down_scale,
                down_out,
                route,
                scale_layout,
            )

        if lora is not None:
            assert down_in is not None
            from kestrel_kernels.moe.lora.cute import apply_moe_lora_down_sum

            apply_moe_lora_down_sum(
                x=down_in,
                topk_weights=route_weights,
                base_down=down_out,
                output=fused,
                lora_a=lora.down_a,
                lora_b=lora.down_b,
                topk_ids=topk_ids,
                active_token_ids=lora.metadata.active_token_ids,
                active_lora_ids=lora.metadata.active_lora_ids,
                active_lora_meta=lora.metadata.active_lora_meta,
                num_experts=self.spec.num_experts,
                scratch=self._lora_scratch(x=x, lora=lora, down=True),
                lora_ranks=lora.lora_ranks,
                active_lora_max_rank=lora.metadata.active_lora_max_rank,
                seg_route=seg_route,
            )
        else:
            from kestrel_kernels.moe_sum_ops import moe_sum

            moe_sum(down_out, fused)
        return fused


def prepare_compact_moe(
    spec: MoeSpec,
    capacity: MoeCapacity,
    device: torch.device,
    configs: dict[str, CuteMoeConfig],
) -> CompactMoeImpl:
    up_config = configs["up"]
    down_config = configs["down"]
    up_is_tcgen = up_config.kernel_type == "tcgen"
    down_is_tcgen = down_config.kernel_type == "tcgen"
    up_block_scheduled = is_block_scheduled_fp8_kernel(up_config.kernel_type)
    down_block_scheduled = is_block_scheduled_fp8_kernel(down_config.kernel_type)
    if up_is_tcgen != down_is_tcgen:
        raise ValueError("compact tcgen MoE requires matching up/down kernel types")
    block_scheduled = up_block_scheduled and down_block_scheduled
    if not (up_is_tcgen or block_scheduled):
        raise ValueError(
            "compact MoE currently supports tcgen and FP8 warp/qmma/wgmma"
        )
    if block_scheduled and up_config.block_m != down_config.block_m:
        raise ValueError("compact block-scheduled MoE requires one shared block_m")
    if spec.top_k != 8:
        raise ValueError("compact MoE currently supports top_k=8")
    if spec.weight_format not in ("bf16", "fp8_e4m3"):
        raise ValueError("compact MoE requires BF16 or FP8 expert weights")
    if spec.weight_format == "bf16" and not up_is_tcgen:
        raise ValueError("compact BF16 MoE requires matching tcgen kernels")
    if device.type != "cuda":
        raise ValueError("compact MoE requires CUDA")

    if capacity.max_loras > 0 and capacity.max_lora_rank > 0:
        # Dev JIT needs lora.cute to set CuTe dump env before any other CuTe import.
        import kestrel_kernels.moe.lora.cute  # noqa: F401

    workspace = _make_workspace()
    _reserve_workspace(
        workspace,
        spec,
        capacity,
        device,
        materialize_dtype=(
            torch.bfloat16
            if spec.weight_format == "bf16"
            else torch.uint8 if up_config.kernel_type == "tcgen" else None
        ),
    )

    route = _make_route_workspace(
        max_tokens=capacity.max_tokens,
        top_k=spec.top_k,
        num_experts=spec.num_experts,
        block_m=up_config.block_m if up_block_scheduled else None,
        device=device,
    )
    return CompactMoeImpl(
        spec=spec,
        capacity=capacity,
        device=device,
        up_config=up_config,
        down_config=down_config,
        route=route,
        workspace=workspace,
    )


__all__ = ["CompactMoeImpl", "prepare_compact_moe"]
